import AppKit

/// Official icons for the agents widefive recognises, embedded so they're sharp and available offline (72 px PNG,
/// drawn at 16-18 pt on a 2x Touch Bar). Sources are noted per icon. Installed desktop apps use their own icon instead.
enum AgentIcons {
    private static var cache: [String: NSImage] = [:]
    private static let lock = NSLock()

    static func image(_ key: String) -> NSImage? {
        lock.lock(); defer { lock.unlock() }
        if let i = cache[key] { return i }
        guard let b64 = data[key], let d = Data(base64Encoded: b64), let img = NSImage(data: d) else { return nil }
        cache[key] = img
        return img
    }

    static var keys: [String] { Array(data.keys) }

    private static let data: [String: String] = [
        // Claude Code for VS Code, Anthropic (verified publisher), VS Code Marketplace
        "claude-code": "",
        // Codex – OpenAI's coding agent, OpenAI (verified publisher), VS Code Marketplace
        "codex": "",
        // Claude by Anthropic, App Store
        "claude": "",
        // ChatGPT, OpenAI, App Store
        "chatgpt": "",
        // Google Gemini, App Store
        "gemini": "",
        // Gemini CLI Companion, Google (verified publisher), Open VSX
        "gemini-cli": "",
        // Grok, xAI, App Store
        "grok": "",
        // cursor.com apple-touch-icon
        "cursor": "",
        // GitHub, App Store
        "github": "",
    ]
}
